def quote(zone, subtotal, weight, kind="physical", service="standard"):
    """Return a delivery quote in cents and business days."""
    if kind == "digital":
        return {"fee": 0, "days": 0}
    if service == "standard":
        return {"fee": 600, "days": 6}
    if service != "express":
        raise ValueError("unsupported service")
    if zone == "north":
        fee, days = 1220, 2
    elif zone == "south":
        fee, days = 2340, 4
    else:
        raise ValueError("unsupported zone")
    fee += (weight - 1) * 160
    if zone == "north" and subtotal >= 22100:
        fee = 0
    return {"fee": fee, "days": days}

